import itertools

def sat_bruteforce(inst):
    m=inst["num_vars"]; clauses=inst["clauses"]
    for bits in itertools.product([False,True],repeat=m):
        ok=True
        for cl in clauses:
            if not any((bits[abs(l)-1] if l>0 else not bits[abs(l)-1]) for l in cl):
                ok=False;break
        if ok: return True
    return False

def threecolor(n,edges):
    adj=[[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v);adj[v].append(u)
    col=[None]*n
    def bt(i):
        if i==n: return True
        for c in range(3):
            if all(col[j]!=c for j in adj[i]):
                col[i]=c
                if bt(i+1): return True
                col[i]=None
        return False
    return bt(0)

def standard_reduce(inst):
    m=inst["num_vars"]; clauses=inst["clauses"]
    # nodes: 0=T,1=F,2=B, then for var v (1..m): pos=3+2*(v-1), neg=4+2*(v-1)
    T,F,B=0,1,2
    edges=[(T,F),(F,B),(B,T)]
    def pos(v): return 3+2*(v-1)
    def neg(v): return 4+2*(v-1)
    for v in range(1,m+1):
        edges.append((pos(v),neg(v)))
        edges.append((pos(v),B))
        edges.append((neg(v),B))
    nxt=3+2*m
    for cl in clauses:
        a,b,c=nxt,nxt+1,nxt+2
        nxt+=3
        edges += [(a,b),(b,c),(c,a)]
        for node,lit in zip((a,b,c),cl):
            edges.append((node, pos(abs(lit)) if lit>0 else neg(abs(lit))))
    return {"n":nxt,"edges":[list(e) for e in edges]}

# enumerate all 3-clauses over m vars (3 distinct vars, no v and -v)
def all_clauses(m):
    res=[]
    for vars3 in itertools.combinations(range(1,m+1),3):
        for signs in itertools.product([1,-1],repeat=3):
            res.append([s*v for s,v in zip(signs,vars3)])
    return res

import random
random.seed(1)
tests=0; mism=0
for m in [3,4]:
    cl=all_clauses(m)
    # test all single clauses and many random pairs/triples
    insts=[]
    for c in cl: insts.append({"num_vars":m,"clauses":[c]})
    for _ in range(300):
        k=random.randint(0,4)
        insts.append({"num_vars":m,"clauses":[random.choice(cl) for _ in range(k)]})
    for inst in insts:
        s=sat_bruteforce(inst)
        g=standard_reduce(inst)
        gv=threecolor(g["n"],g["edges"])
        tests+=1
        if s!=gv:
            mism+=1
            if mism<=10:
                print("MISMATCH sat=",s,"color=",gv,inst)
print("tests",tests,"mismatches",mism)
